u8 CalcMoveSplit(u8 bankAtk, u16 move, u8 bankDef)
{
	if ((CheckTableForMove(move, gMovesThatChangePhysicality)
	|| ((move == MOVE_TERABLAST || move == MOVE_TERASTARSTORM) && TeraTypeActive(bankAtk)))
	&&  SPLIT(move) != SPLIT_STATUS)
	{
		u32 attack = gBattleMons[bankAtk].attack;
		u32 spAttack = gBattleMons[bankAtk].spAttack;

		APPLY_QUICK_STAT_MOD(attack, STAT_STAGE(bankAtk, STAT_STAGE_ATK));
		APPLY_QUICK_STAT_MOD(spAttack, STAT_STAGE(bankAtk, STAT_STAGE_SPATK));

		if (spAttack >= attack)
			return SPLIT_SPECIAL;
		else
			return SPLIT_PHYSICAL;
	}
	else if (move == MOVE_SHELLSIDEARM
	&& bankAtk != bankDef) //Indicator to just use the base physicality
	{
		return gNewBS->shellSideArmSplit[bankAtk][bankDef];
	}

	#ifdef OLD_MOVE_SPLIT
		if (gBattleMoves[move].type < TYPE_FIRE)
			return SPLIT_PHYSICAL;
		else
			return SPLIT_SPECIAL;
	#else
		return SPLIT(move);
	#endif
}

u8 ScriptGiveMon(u16 species, u8 level, u16 item, unusedArg u32 unused1, unusedArg u32 customGivePokemon, unusedArg u8 ballType)
{
	u8 sentToPc;
	struct Pokemon mon;

	CreateMon(&mon, species, level, 32, 0, 0, 0, 0);
	SetMonData(&mon, MON_DATA_HELD_ITEM, &item);

	#ifdef GIVEPOKEMON_BALL_HACK
	if (ballType != 0)
		mon.pokeball = ballType;
	#endif

	#ifdef FLAG_HIDDEN_ABILITY
	if (FlagGet(FLAG_HIDDEN_ABILITY))
	{
		mon.hiddenAbility = TRUE;
		FlagClear(FLAG_HIDDEN_ABILITY);
	}
	#endif

	#ifdef FLAG_GIGANTAMAXABLE
	if (FlagGet(FLAG_GIGANTAMAXABLE))
	{
		mon.gigantamax = TRUE;
		FlagClear(FLAG_GIGANTAMAXABLE);
	}
	#endif

	#ifdef FLAG_CUSTOM_TERA_TYPE
	if (FlagGet(FLAG_CUSTOM_TERA_TYPE))
	{
		mon.teratype = VarGet(Var8008);
		FlagClear(FLAG_CUSTOM_TERA_TYPE);
	}
	#endif

	#ifdef GIVEPOKEMON_CUSTOM_HACK
	if (customGivePokemon != 0)
	{
		u8 i;
		u16* moves = &Var8000; //-0x8003
		u8 nature = Var8004;
		bool8 shiny = Var8005;
		u16* ivs = &Var8006; //-0x800B

		for (i = 0; i < MAX_MON_MOVES; ++i)
		{
			if (moves[i] < MOVES_COUNT)
				SetMonData(&mon, MON_DATA_MOVE1 + i, &moves[i]);
		}

		for (i = 0; i < NUM_STATS; ++i)
			SetMonData(&mon, MON_DATA_HP_IV + i, &ivs[i]);

		if (nature >= NUM_NATURES)
		{
			#ifdef SYNCHRONIZE_GIFT_POKEMON
			if (GetMonAbility(&gPlayerParty[0]) == ABILITY_SYNCHRONIZE) //Lead has Synchronize
				nature = GetNature(&gPlayerParty[0]); //Match lead
			else
			#endif
			nature = Random() % NUM_NATURES;
		}

		GiveMonNatureAndAbility(&mon, nature, GetMonData(&mon, MON_DATA_PERSONALITY, NULL) & 1, shiny ? TRUE : IsMonShiny(&mon), FALSE, FALSE);
		CalculateMonStats(&mon);
	}
	else
	#endif
	{
		#ifdef SYNCHRONIZE_GIFT_POKEMON
		if (GetMonAbility(&gPlayerParty[0]) == ABILITY_SYNCHRONIZE) //Lead has Synchronize
		{
			u8 nature = GetNature(&gPlayerParty[0]); //Match lead
			GiveMonNatureAndAbility(&mon, nature, GetMonData(&mon, MON_DATA_PERSONALITY, NULL) & 1, IsMonShiny(&mon), FALSE, FALSE);
			CalculateMonStats(&mon);
		}
		#endif
	}

	HealMon(&mon);
	sentToPc = GiveMonToPlayer(&mon);

	switch(sentToPc) {
		case 0:
		case 1:
			SetMonPokedexFlags(&mon);
			break;
	}

	return sentToPc;
}

static void DetermineEggAbility(struct Pokemon* egg, unusedArg struct BoxPokemon* father, struct BoxPokemon* mother)
{
	#ifdef SPECIES_DITTO
	if (GetBoxMonData(mother, MON_DATA_SPECIES, NULL) == SPECIES_DITTO)
		mother = father; //Get Hidden Ability from father instead
	#endif

	if (((struct Pokemon*) mother)->hiddenAbility)
	{
		if (Random() % 100 < 60) //60 % chance to pass down Hidden Ability
			egg->hiddenAbility = TRUE;
	}
	else
	{
		if (gBaseStats[GetMonData(egg, MON_DATA_SPECIES, NULL)].ability2)
		{
			u8 abilityNum = GetBoxMonData(mother, MON_DATA_ALT_ABILITY, NULL);

			if (Random() % 100 >= 80) //80 % chance to pass down slotted ability
				abilityNum ^= 1;
			SetMonData(egg, MON_DATA_ALT_ABILITY, &abilityNum);
		}
	}
}

static u16 DexNavGenerateHiddenAbility(u16 species, u8 searchLevel)
{
	bool8 genAbility = FALSE;
	u16 randVal = Random() % 100;

	if (searchLevel < 5)
	{
		#if (SEARCHLEVEL0_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL0_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}
	else if (searchLevel < 10)
	{
		#if (SEARCHLEVEL5_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL5_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}
	else if (searchLevel < 25)
	{
		#if (SEARCHLEVEL10_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL10_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}
	else if (searchLevel < 50)
	{
		#if (SEARCHLEVEL25_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL25_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}
	else if (searchLevel < 100)
	{
		#if (SEARCHLEVEL50_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL50_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}
	else
	{
		#if (SEARCHLEVEL100_ABILITYCHANCE != 0)
		if (randVal < SEARCHLEVEL100_ABILITYCHANCE)
			genAbility = TRUE;
		#endif
	}

	#ifdef UNBOUND
	if (genAbility
	&& !FlagGet(FLAG_SYS_GAME_CLEAR)
	&& VarGet(VAR_GAME_DIFFICULTY) >= OPTIONS_EXPERT_DIFFICULTY
	&& gBaseStats[species].hiddenAbility == ABILITY_IMPOSTER)
		genAbility = FALSE; //Don't allow Imposter until the post-game
	#endif

	if (genAbility && gBaseStats[species].hiddenAbility != ABILITY_NONE
	&& GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT)) //Only give hidden ability if Pokemon has been caught before
		return GetHiddenAbility(species);
	else
	{
		//Pick a normal ability of that Pokemon
		u16 ability;
		u16 ability1 = GetAbility1(species);
		u16 ability2 = GetAbility2(species);

		if (ability2 != ABILITY_NONE)
			ability = (randVal & 1) == 0 ? ability1 : ability2;
		else
			ability = ability1;

		return ability;
	}
}

u8 GetRaidSpeciesAbilityNum(u16 species)
{
	u32 i = 0;
	u8 numStars = gRaidBattleStars;
	const struct RaidData* raid = &gRaidsByMapSection[GetRaidMapSectionId()][numStars];

	if (IsGigantamaxSpecies(species))
		return RAID_ABILITY_RANDOM_ALL; //Gigantamax Pokemon can have any one of their abilities

	if (raid->data != NULL)
	{
		for (i = 0; i < raid->amount; ++i)
		{
			if (raid->data[i].species == species) //Max one species per dataset
				return raid->data[i].ability;
		}
	}

	return RAID_ABILITY_RANDOM_1_2;
}

bool8 IsZCrystal(u16 item)
{
	return ItemId_GetHoldEffect(item) == ITEM_EFFECT_Z_CRYSTAL;
}

bool8 IsTypeZCrystal(u16 item, u8 moveType)
{
	return IsZCrystal(item) && ItemId_GetHoldEffectParam(item) == moveType && !IsSpecialZCrystal(item);
}

move_t GetTypeBasedZMove(u16 move, u8 bank)
{
	u8 moveType = gBattleMoves[move].type;

	if (move == MOVE_WEATHERBALL || move == MOVE_AURAWHEEL || move == MOVE_TERRAINPULSE)
		moveType = GetMoveTypeSpecial(bank, move);

	if (moveType < TYPE_FIRE)
		return MOVE_BREAKNECK_BLITZ_P + (moveType * 2) + CalcMoveSplit(bank, move, bank);
	else if (moveType >= TYPE_FAIRY)
		return MOVE_TWINKLE_TACKLE_P + ((moveType - TYPE_FAIRY) * 2) + CalcMoveSplit(bank, move, bank);
	else
		return MOVE_BREAKNECK_BLITZ_P + ((moveType - 1) * 2) + CalcMoveSplit(bank, move, bank);
}

move_t GetSpecialZMove(u16 move, u16 species, u16 item)
{
	bool8 isSpecialZCrystal = FALSE;

	for (u32 i = 0; i < ARRAY_COUNT(sSpecialZMoveTable); ++i)
	{
		if (sSpecialZMoveTable[i].item == item)
		{
			isSpecialZCrystal = TRUE;

			if (sSpecialZMoveTable[i].species == species
			&&  sSpecialZMoveTable[i].move == move)
			{
				return sSpecialZMoveTable[i].zmove;
			}
		}
	}

	if (isSpecialZCrystal)
		return 0xFFFF;
	else
		return MOVE_NONE;
}

move_t CanUseZMove(u8 bank, u8 moveIndex, u16 move)
{
	if (IS_TRANSFORMED(bank))
		return MOVE_NONE;

	if (move == MOVE_NONE)
		move = gBattleMons[bank].moves[moveIndex];

	#if (defined VAR_KEYSTONE && !defined DEBUG_MEGA)
	//Z-Moves can't be used until receieving a Keystone
	if (!(gBattleTypeFlags & (BATTLE_TYPE_FRONTIER | BATTLE_TYPE_LINK))) //Z-Moves can always be used in these battles
	{
		u8 position = GetBattlerPosition(bank);
		if (position == B_POSITION_PLAYER_LEFT || (!IsTagBattle() && position == B_POSITION_PLAYER_RIGHT))
		{
			u16 keystone = VarGet(VAR_KEYSTONE);
			if (keystone == ITEM_NONE)
				return MOVE_NONE;
		}
	}
	#endif

	if (IsMegaZMoveBannedBattle()
	|| IsMega(bank)
	|| IsRedPrimal(bank)
	|| IsBluePrimal(bank))
		return MOVE_NONE;

	u16 item = GetBankPartyData(bank)->item; //Direct access for runtime speed

	if (IsZCrystal(item) || item == ITEM_ULTRANECROZIUM_Z) //The only "Mega Stone" that let's you use a Z-Move
	{
		u16 zMove = GetSpecialZMove(move, SPECIES(bank), item);
		if (zMove != MOVE_NONE && zMove != 0xFFFF) //There's a special Z-Move
			return zMove;

		if (move != MOVE_NONE && zMove != 0xFFFF //Special Z-Crystal
		&& gBattleMoves[move].type == ItemId_GetHoldEffectParam(item))
		{
			if (SPLIT(move) == SPLIT_STATUS)
				return 0xFFFF;
			else
				return GetTypeBasedZMove(move, bank);
		}
	}

	return MOVE_NONE;
}

void SetZEffect(void)
{
	int i;

	gNewBS->zMoveData.runningZEffect = TRUE;

	if (gNewBS->zMoveData.effect == Z_EFFECT_CURSE) {
		if (IsOfType(gBankAttacker, TYPE_GHOST))
			gNewBS->zMoveData.effect = Z_EFFECT_RECOVER_HP;
		else
			gNewBS->zMoveData.effect = Z_EFFECT_ATK_UP_1;
	}

	gBattleScripting.bank = gBankAttacker;

	switch (gNewBS->zMoveData.effect) {
		case Z_EFFECT_RESET_STATS:
			for (i = 0; i < BATTLE_STATS_NO-1; ++i)
			{
				if (gBattleMons[gBankAttacker].statStages[i] < 6)
					gBattleMons[gBankAttacker].statStages[i] = 6;
				}
			BattleScriptPush(gBattlescriptCurrInstr + 5);
			gBattlescriptCurrInstr = BattleScript_StatsResetZMove - 5;
			break;

		case Z_EFFECT_ALL_STATS_UP_1:
			if (!MainStatsMaxed(gBankAttacker))
			{
				for (i = 0; i < STAT_ACC-1; ++i) //Doesn't increase Acc or Evsn
				{
					if (gBattleMons[gBankAttacker].statStages[i] < STAT_STAGE_MAX)
						++gBattleMons[gBankAttacker].statStages[i];
				}

				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_AllStatsUpZMove - 5;
			}
			break;

		case Z_EFFECT_BOOST_CRITS:
			if (!(gBattleMons[gBankAttacker].status2 & STATUS2_FOCUS_ENERGY))
			{
				gBattleMons[gBankAttacker].status2 |= STATUS2_FOCUS_ENERGY;
				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_BoostCritsZMove - 5;
			}
			break;

		case Z_EFFECT_FOLLOW_ME:
			gSideTimers[SIDE(gBankAttacker)].followmeTimer = 1;
			gSideTimers[SIDE(gBankAttacker)].followmeTarget = gBankAttacker;
			BattleScriptPush(gBattlescriptCurrInstr + 5);
			gBattlescriptCurrInstr = BattleScript_FollowMeZMove - 5;
			break;

		case Z_EFFECT_RECOVER_HP:
			if (!BATTLER_MAX_HP(gBankAttacker))
			{
				gBattleMoveDamage = (-1) * gBattleMons[gBankAttacker].maxHP;
				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_RecoverHPZMove - 5;
			}
			break;

		case Z_EFFECT_RESTORE_REPLACEMENT_HP:
			gNewBS->zMoveData.healReplacement = TRUE;
			BattleScriptPush(gBattlescriptCurrInstr + 5);
			gBattlescriptCurrInstr = BattleScript_SetUpHealReplacementZMove - 5;
			break;

		case Z_EFFECT_ATK_UP_1:
		case Z_EFFECT_DEF_UP_1:
		case Z_EFFECT_SPD_UP_1:
		case Z_EFFECT_SPATK_UP_1:
		case Z_EFFECT_SPDEF_UP_1:
		case Z_EFFECT_ACC_UP_1:
		case Z_EFFECT_EVSN_UP_1:
			if (!ChangeStatBuffs(SET_STAT_BUFF_VALUE(1), gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_1 + 1, MOVE_EFFECT_AFFECTS_USER, 0))
			{
				gBattleScripting.animArg1 = 0xE + (gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_1 + 1);
				gBattleScripting.animArg2 = 0;
				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_StatUpZMove - 5;
			}
			break;

		case Z_EFFECT_ATK_UP_2:
		case Z_EFFECT_DEF_UP_2:
		case Z_EFFECT_SPD_UP_2:
		case Z_EFFECT_SPATK_UP_2:
		case Z_EFFECT_SPDEF_UP_2:
		case Z_EFFECT_ACC_UP_2:
		case Z_EFFECT_EVSN_UP_2:
			if (!ChangeStatBuffs(SET_STAT_BUFF_VALUE(2), gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_2 + 1, MOVE_EFFECT_AFFECTS_USER, 0))
			{
				gBattleScripting.animArg1 = 0xE + (gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_2 + 1);
				gBattleScripting.animArg2 = 0;
				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_StatUpZMove - 5;
			}
			break;

		case Z_EFFECT_ATK_UP_3:
		case Z_EFFECT_DEF_UP_3:
		case Z_EFFECT_SPD_UP_3:
		case Z_EFFECT_SPATK_UP_3:
		case Z_EFFECT_SPDEF_UP_3:
		case Z_EFFECT_ACC_UP_3:
		case Z_EFFECT_EVSN_UP_3:
			if (!ChangeStatBuffs(SET_STAT_BUFF_VALUE(3), gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_3 + 1, MOVE_EFFECT_AFFECTS_USER, 0))
			{
				gBattleScripting.animArg1 = 0xE + (gNewBS->zMoveData.effect - Z_EFFECT_ATK_UP_3 + 1);
				gBattleScripting.animArg2 = 0;
				BattleScriptPush(gBattlescriptCurrInstr + 5);
				gBattlescriptCurrInstr = BattleScript_StatUpZMove - 5;
			}
			break;
	}

	gNewBS->zMoveData.runningZEffect = FALSE;
}

u16 ReplaceWithZMoveRuntime(u8 bankAtk, u16 move)
{
	if (gNewBS->zMoveData.toBeUsed[bankAtk]
	&& !gNewBS->zMoveData.used[bankAtk]
	&& SPLIT(move) != SPLIT_STATUS)
	{
		u16 zMove = CanUseZMove(bankAtk, 0xFF, move);
		if (zMove != MOVE_NONE)
			move = zMove;
	}
	else if (IsDynamaxed(bankAtk) || (gNewBS->dynamaxData.toBeUsed[bankAtk] && !gNewBS->dynamaxData.used[bankAtk]))
	{
		if (IsRaidBattle() && bankAtk == BANK_RAID_BOSS && IsRaidBossUsingRegularMove(bankAtk, move))
			return move; //This turn the raid boss isn't using a Max Move

		u16 maxMove = GetMaxMoveByMove(bankAtk, move);
		if (maxMove != MOVE_NONE)
			move = maxMove;
	}

	return move;
}

